sw="""const C='flixora-shell-v1',S=['./','./index.html','./styles.css','./app.js','./manifest.webmanifest','./assets/icon.svg','./data/titles.json','./data/services.json'];self.addEventListener('install',e=>e.waitUntil(caches.open(C).then(c=>c.addAll(S)).then(()=>self.skipWaiting())));self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(k=>Promise.all(k.filter(x=>x!==C).map(x=>caches.delete(x)))).then(()=>self.clients.claim())));self.addEventListener('fetch',e=>{let r=e.request,u=new URL(r.url);if(r.method!=='GET'||u.origin!==location.origin)return;if(r.mode==='navigate'){e.respondWith(fetch(r).then(x=>{caches.open(C).then(c=>c.put('./index.html',x.clone()));return x}).catch(()=>caches.match('./index.html')));return}e.respondWith(caches.match(r).then(x=>x||fetch(r).then(x=>{if(x.ok)caches.open(C).then(c=>c.put(r,x.clone()));return x})))});"""
